// Command gen builds the vendors package's data from the IEEE Registration
// Authority's public MA-L, MA-M and MA-S assignment listings. Run it with
// `go generate ./vendors`, or point -from at a directory holding oui.csv,
// mam.csv and oui36.csv to build from files downloaded earlier.
package main

import (
	"bytes"
	"compress/gzip"
	"encoding/csv"
	"flag"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
	"time"
)

var registries = []struct {
	file, url string
	digits    int // hex digits of the assignment: 24, 28 and 36 bit prefixes
}{
	{"oui.csv", "https://standards-oui.ieee.org/oui/oui.csv", 6},
	{"mam.csv", "https://standards-oui.ieee.org/oui28/mam.csv", 7},
	{"oui36.csv", "https://standards-oui.ieee.org/oui36/oui36.csv", 9},
}

// Legal forms trimmed from the end of organization names. The separator
// before them is required, so "Cisco" keeps its "co".
var legalSuffix = regexp.MustCompile(`(?i)[\s,&]+(?:incorporated|inc|corporation|corporate|corp|company|co|limited|ltd|l\.?l\.?c|gmbh|ag|kg|ab|a/s|asa|as|oyj|oy|s\.?a\.?s|s\.?a|s\.?r\.?l|s\.?p\.?a|b\.?v|n\.?v|pty|pte|plc|k\.?k|kft|s\.?r\.?o|sp\.?\s*z\s*o\.?\s*o|sdn\.?\s*bhd|bhd)\.?$`)

var spaces = regexp.MustCompile(`\s+`)

// cleanName shortens an organization name for display, e.g. "Samsung
// Electronics Co.,Ltd" to "Samsung Electronics". Casing is kept as listed.
func cleanName(name string) string {
	name = strings.TrimSpace(spaces.ReplaceAllString(name, " "))
	short := name
	for {
		next := strings.TrimRight(legalSuffix.ReplaceAllString(short, ""), " ,&.-")
		if next == short {
			break
		}
		short = next
	}
	// Nothing but legal forms (e.g. "Co., Ltd."): keep the name as listed.
	if len(short) < 2 || legalSuffix.MatchString(" "+short) {
		return name
	}
	return short
}

// skipped reports names that don't identify a manufacturer: assignments
// whose owner asked to be unlisted, and the MA-L blocks the registry split
// into MA-M and MA-S assignments.
func skipped(name string) bool {
	switch strings.ToLower(name) {
	case "", "private", "ieee registration authority":
		return true
	}
	return false
}

func open(dir, file, url string) (io.ReadCloser, error) {
	if dir != "" {
		return os.Open(filepath.Join(dir, file))
	}
	resp, err := http.Get(url)
	if err != nil {
		return nil, err
	}
	if resp.StatusCode != http.StatusOK {
		resp.Body.Close()
		return nil, fmt.Errorf("GET %s: %s", url, resp.Status)
	}
	return resp.Body, nil
}

func main() {
	from := flag.String("from", "", "directory with oui.csv, mam.csv and oui36.csv (default: download them)")
	flag.Parse()

	var lines []string
	for _, registry := range registries {
		body, err := open(*from, registry.file, registry.url)
		if err != nil {
			log.Fatal(err)
		}
		records, err := csv.NewReader(body).ReadAll()
		body.Close()
		if err != nil {
			log.Fatalf("%s: %v", registry.file, err)
		}

		count := 0
		for _, record := range records[1:] { // header: Registry,Assignment,Organization Name,...
			if len(record) < 3 || len(record[1]) != registry.digits {
				log.Fatalf("%s: unexpected record %q", registry.file, record)
			}
			name := cleanName(record[2])
			if skipped(name) {
				continue
			}
			lines = append(lines, strings.ToLower(record[1])+"\t"+name)
			count++
		}
		log.Printf("%s: %d assignments", registry.file, count)
	}
	slices.Sort(lines)

	var data bytes.Buffer
	zw, _ := gzip.NewWriterLevel(&data, gzip.BestCompression)
	for _, line := range lines {
		fmt.Fprintln(zw, line)
	}
	if err := zw.Close(); err != nil {
		log.Fatal(err)
	}
	if err := os.WriteFile("oui.tsv.gz", data.Bytes(), 0o644); err != nil {
		log.Fatal(err)
	}

	generated := fmt.Sprintf(`// Code generated by vendors/gen; DO NOT EDIT.

package vendors

// DataDate is when the IEEE listings in oui.tsv.gz were downloaded.
const DataDate = %q
`, time.Now().UTC().Format("2006-01-02"))
	if err := os.WriteFile("data_date.go", []byte(generated), 0o644); err != nil {
		log.Fatal(err)
	}

	log.Printf("wrote %d assignments, %d KB", len(lines), data.Len()/1024)
}
